package com.luizotavio.academia.controller;
import com.luizotavio.academia.entity.*; import com.luizotavio.academia.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/avaliacoes") public class AvaliacaoFisicaController { private final AvaliacaoFisicaRepository repo; private final AlunoRepository alunos; public AvaliacaoFisicaController(AvaliacaoFisicaRepository r,AlunoRepository a){repo=r;alunos=a;} @GetMapping public List<AvaliacaoFisica> listar(){return repo.findAll();} @GetMapping("/aluno/{alunoId}") public List<AvaliacaoFisica> porAluno(@PathVariable Long alunoId){return repo.findByAlunoId(alunoId);} @PostMapping("/aluno/{alunoId}") public ResponseEntity<AvaliacaoFisica> criar(@PathVariable Long alunoId,@RequestBody AvaliacaoFisica av){return alunos.findById(alunoId).map(a->{av.setId(null);av.setAluno(a);return ResponseEntity.status(HttpStatus.CREATED).body(repo.save(av));}).orElse(ResponseEntity.notFound().build());} }
